89	// running the binary
90	// ---------------------------------------------------------------------------
91	
92	struct Run {
93	    rc: i32,
94	    out: Vec<u8>,
95	    err: Vec<u8>,
96	}
97	
98	/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
99	/// wrapper, with the permfail shim preloaded and a trace file configured.
100	fn run_keygen(key: &Path, umask: u32, so: &Path, extra_env: &[(&str, &str)], trace: &Path) -> Run {
101	    let mut cmd = Command::new("/bin/sh");
102	    cmd.arg("-c")
103	        .arg(format!("umask {umask:04o}; exec \"$@\""))
104	        .arg("sh")
105	        .arg(bin())
106	        .arg("keygen")
107	        .arg(key)
108	        .env("LD_PRELOAD", so)
109	        .env("WRAPFILE_TEST_TRACE_FILE", trace);
110	    for (k, v) in extra_env {
111	        cmd.env(k, v);
112	    }
113	    let o = cmd.output().unwrap();
114	    Run {
115	        rc: o.status.code().unwrap_or(-1),
116	        out: o.stdout,
117	        err: o.stderr,
118	    }
119	}
