121	// ---------------------------------------------------------------------------
122	// shim trace log
123	// ---------------------------------------------------------------------------
124	
125	struct Event {
126	    kind: String,
127	    attrs: HashMap<String, String>,
128	}
129	
130	impl Event {
131	    fn get(&self, key: &str) -> Option<&str> {
132	        self.attrs.get(key).map(String::as_str)
133	    }
134	
135	    fn ret(&self) -> Option<i64> {
136	        self.get("ret").and_then(|v| v.parse().ok())
137	    }
138	
139	    fn off(&self) -> Option<u64> {
140	        self.get("off").and_then(|v| v.parse().ok())
141	    }
142	
143	    fn hex_bytes(&self) -> Option<Vec<u8>> {
144	        let hex = self.get("hex")?;
145	        assert_eq!(hex.len() % 2, 0, "odd hex in trace line");
146	        Some(
147	            (0..hex.len() / 2)
148	                .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
149	                .collect(),
150	        )
151	    }
152	}
153	
154	fn parse_trace(path: &Path) -> Vec<Event> {
155	    let text = fs::read_to_string(path).unwrap();
156	    text.lines()
157	        .map(|line| {
158	            let mut it = line.split_whitespace();
159	            let kind = it.next().unwrap_or("").to_string();
160	            let attrs = it
161	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
162	                .collect();
163	            Event { kind, attrs }
164	        })
165	        .collect()
166	}
167	
168	/// Create the trace file up front (mode 0644) so that it stays readable even
169	/// when the child runs under umask 0777 -- the shim opens it O_APPEND.
170	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
171	    let p = dir.join(name);
172	    fs::File::create(&p).unwrap();
173	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
174	    p
175	}
176	
177	/// The successful write() calls, in call order: (offset, bytes landed, bytes).
178	fn successful_writes(events: &[Event]) -> Vec<(u64, u64, Option<Vec<u8>>)> {
179	    events
180	        .iter()
181	        .filter(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
182	        .map(|e| {
183	            (
184	                e.off().expect("WRITE event needs off="),
185	                e.ret().unwrap() as u64,
186	                e.hex_bytes(),
187	            )
188	        })
189	        .collect()
190	}
191	
192	/// The landed writes must tile [0, total) exactly: the first starts at 0,
193	/// each continues where the previous ended -- no byte written twice, none
194	/// skipped.
195	fn assert_writes_tile(writes: &[(u64, u64, Option<Vec<u8>>)], total: usize, context: &str) {
196	    assert!(!writes.is_empty(), "{context}: no bytes were ever written");
197	    let mut expect = 0u64;
198	    for (off, n, _) in writes {
199	        assert_eq!(
200	            *off, expect,
201	            "{context}: write at offset {off} overlaps or leaves a gap (expected {expect})"
202	        );
203	        expect += n;
204	    }
205	    assert_eq!(
206	        expect as usize, total,
207	        "{context}: writes must add up to exactly {total} bytes, got {expect}"
208	    );
209	}
210	
211	fn reconstruct(writes: &[(u64, u64, Option<Vec<u8>>)]) -> Vec<u8> {
212	    writes
213	        .iter()
214	        .flat_map(|(_, _, hex)| hex.clone().expect("TRACE_BYTES must be on"))
215	        .collect()
216	}
217	
218	/// The write() calls that accepted 0 bytes while reporting no error.
219	fn zero_writes<'a>(events: &'a [Event]) -> Vec<&'a Event> {
220	    events
221	        .iter()
222	        .filter(|e| e.kind == "WRITE" && e.ret() == Some(0))
223	        .collect()
224	}
225	
226	/// Bytes the program handed to write() calls that accepted none of them.
227	fn rejected_offerings(events: &[Event]) -> Vec<u8> {
228	    zero_writes(events)
229	        .iter()
230	        .flat_map(|e| e.hex_bytes().expect("TRACE_BYTES must be on"))
231	        .collect()
232	}
