234	// ---------------------------------------------------------------------------
235	// filesystem assertions
236	// ---------------------------------------------------------------------------
237	
238	fn mode_of(path: &Path) -> u32 {
239	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
240	}
241	
242	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
243	    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
244	}
245	
246	/// The full success contract: exit 0, empty stderr, only the save-location
247	/// line on stdout, and exactly 32 raw key bytes in a 0600 file that leaks
248	/// nowhere.
249	fn assert_success(key: &Path, run: &Run) -> Vec<u8> {
250	    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
251	    assert!(
252	        run.err.is_empty(),
253	        "stderr must be empty on success, got {}",
254	        String::from_utf8_lossy(&run.err)
255	    );
256	    assert_eq!(
257	        run.out,
258	        format!("Key saved to {}\n", key.display()).into_bytes(),
259	        "stdout must be exactly the save-location message"
260	    );
261	
262	    let meta = fs::metadata(key).expect("key file must exist on success");
263	    assert_eq!(meta.len() as usize, KEY_LEN, "key must be exactly 32 bytes");
264	    assert_eq!(
265	        meta.mode() & 0o7777,
266	        MODE_0600,
267	        "key file mode must be exactly 0600"
268	    );
269	
270	    let bytes = fs::read(key).unwrap();
271	    assert_eq!(bytes.len(), KEY_LEN);
272	    assert!(bytes.iter().any(|&b| b != 0), "key must not be all zeroes");
273	    assert!(
274	        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
275	        "key bytes must never appear on stdout/stderr"
276	    );
277	    bytes
278	}
279	
280	/// The failure contract shared by the write-error and fsync-error tests:
281	/// exit 1, an explanation on stderr, no success output, no leaked key
282	/// material, and no trace of this invocation left in the parent directory.
283	fn assert_failed_cleanly(
284	    key: &Path,
285	    run: &Run,
286	    dir: &Path,
287	    allowed_entries: &[&str],
288	    leaked_candidate: &[u8],
289	) {
290	    assert_eq!(run.rc, 1, "an unfinishable save must exit 1");
291	    assert!(
292	        run.out.is_empty(),
293	        "no success message may be printed on failure, got {}",
294	        String::from_utf8_lossy(&run.out)
295	    );
296	    assert!(!run.err.is_empty(), "stderr must explain the failure");
297	    let stderr = String::from_utf8_lossy(&run.err);
298	    assert!(
299	        stderr.contains(&key.display().to_string()),
300	        "stderr should name the target path, got: {stderr}"
301	    );
302	    assert!(
303	        !contains_slice(&run.out, leaked_candidate)
304	            && !contains_slice(&run.err, leaked_candidate),
305	        "key material must never leak to stdout/stderr, even on failure"
306	    );
307	
308	    assert!(
309	        !key.exists(),
310	        "the file this invocation created must be removed after the failure"
311	    );
312	    let mut leftovers: Vec<String> = fs::read_dir(dir)
313	        .unwrap()
314	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
315	        .filter(|n| !allowed_entries.contains(&n.as_str()))
316	        .collect();
317	    leftovers.sort();
318	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
319	}
320	
321	/// Key material must not surface on stdout/stderr in any encoding: not as
322	/// raw bytes, and not as a hex (or other text) rendering.
323	fn assert_key_material_not_leaked(run: &Run, material: &[u8], what: &str) {
324	    assert!(
325	        !contains_slice(&run.out, material) && !contains_slice(&run.err, material),
326	        "{what} must never appear on stdout/stderr as raw bytes"
327	    );
328	    let hex: String = material.iter().map(|b| format!("{b:02x}")).collect();
329	    let out = String::from_utf8_lossy(&run.out);
330	    let err = String::from_utf8_lossy(&run.err);
331	    assert!(
332	        !out.contains(&hex) && !err.contains(&hex),
333	        "{what} must never appear on stdout/stderr in hex form"
334	    );
335	}
