337	// A pre-existing object that must survive a failed keygen byte-for-byte.
338	struct Sentinel {
339	    path: PathBuf,
340	    bytes: Vec<u8>,
341	    mode: u32,
342	    inode: u64,
343	}
344	
345	impl Sentinel {
346	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
347	        let path = dir.join(name);
348	        fs::write(&path, bytes).unwrap();
349	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
350	        let meta = fs::metadata(&path).unwrap();
351	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
352	    }
353	
354	    fn assert_untouched(&self) {
355	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
356	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
357	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
358	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
359	    }
360	}
