366	#[test]
367	fn partial_writes_save_the_full_key_exactly_once() {
368	    let Some(so) = permfail_so() else {
369	        eprintln!("skipping: permfail shim not available on this target");
370	        return;
371	    };
372	
373	    for umask in UMASKS {
374	        let tmp = Tmp::new("partial");
375	        let key = tmp.child("key");
376	        let trace = prepare_trace(&tmp.path, "trace.log");
377	
378	        // The kernel accepts only one byte per write() call.
379	        let run = run_keygen(
380	            &key,
381	            umask,
382	            &so,
383	            &[
384	                ("WRAPFILE_TEST_PARTIAL_WRITE", "1"),
385	                ("WRAPFILE_TEST_TRACE_BYTES", "1"),
386	            ],
387	            &trace,
388	        );
389	
390	        let on_disk = assert_success(&key, &run);
391	
392	        let events = parse_trace(&trace);
393	        let writes = successful_writes(&events);
394	        assert!(
395	            writes.len() >= KEY_LEN,
396	            "one-byte writes should mean at least 32 write() calls, got {}",
397	            writes.len()
398	        );
399	        // No written byte repeated, no later byte dropped...
400	        assert_writes_tile(&writes, KEY_LEN, "partial writes");
401	        // ...and the bytes the program handed to the kernel are exactly the
402	        // bytes that ended up in the file -- nothing reordered or invented.
403	        assert_eq!(
404	            reconstruct(&writes),
405	            on_disk,
406	            "file content must equal the concatenation of the write() calls"
407	        );
408	
409	        // Success was reported only after the data was synced to disk.
410	        let last_write = events
411	            .iter()
412	            .rposition(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
413	            .unwrap();
414	        let fsynced = events
415	            .iter()
416	            .position(|e| e.kind == "FSYNC" && e.ret() == Some(0))
417	            .expect("the key must be fsynced before success is reported");
418	        assert!(fsynced > last_write, "fsync must follow the last write");
419	    }
420	}
