465	fn unrecoverable_write_error_fails_and_removes_the_partial_file() {
466	    let Some(so) = permfail_so() else {
467	        eprintln!("skipping: permfail shim not available on this target");
468	        return;
469	    };
470	
471	    let tmp = Tmp::new("write-error");
472	    let key = tmp.child("key");
473	    let sibling = Sentinel::file(&tmp.path, "sibling", b"do-not-touch", 0o644);
474	    let parent_mode_before = mode_of(&tmp.path);
475	    let trace = prepare_trace(&tmp.path, "trace.log");
476	
477	    // Ten bytes land (4 + 4 + 2), then every further write fails with EIO.
478	    let run = run_keygen(
479	        &key,
480	        0o022,
481	        &so,
482	        &[
483	            ("WRAPFILE_TEST_PARTIAL_WRITE", "4"),
484	            ("WRAPFILE_TEST_FAIL_WRITE_AFTER", "10"),
485	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
486	        ],
487	        &trace,
488	    );
489	
490	    let events = parse_trace(&trace);
491	    let writes = successful_writes(&events);
492	    // The failure really happened mid-write: part of the key was on disk.
493	    assert_writes_tile(&writes, 10, "writes before the error");
494	    assert!(
495	        events
496	            .iter()
497	            .any(|e| e.kind == "WRITE" && e.get("errno") == Some("EIO")),
498	        "the unrecoverable write error must have been injected"
499	    );
500	    assert!(
501	        events.iter().all(|e| e.kind != "FSYNC"),
502	        "an incomplete key must never be synced as if complete"
503	    );
504	    let partial_key = reconstruct(&writes);
505	    assert_eq!(partial_key.len(), 10);
506	
507	    assert_failed_cleanly(&key, &run, &tmp.path, &["sibling", "trace.log"], &partial_key);
508	    sibling.assert_untouched();
509	    assert_eq!(
510	        mode_of(&tmp.path),
511	        parent_mode_before,
512	        "parent directory permissions must be untouched"
513	    );
514	
515	    // The failure was transient: a retry without the fault saves a full key.
516	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
517	    let run2 = run_keygen(&key, 0o022, &so, &[], &trace2);
518	    assert_success(&key, &run2);
519	    sibling.assert_untouched();
520	}
