678	        "an incomplete key must never be synced as if complete"
679	    );
680	    let partial_key = reconstruct(&writes);
681	    assert_eq!(partial_key.len(), 10);
682	    // Landed prefix + rejected remainder reconstruct the full key.
683	    let mut full_key = partial_key.clone();
684	    full_key.extend(rejected_offerings(&events));
685	    assert_eq!(full_key.len(), KEY_LEN);
686	
687	    assert_failed_cleanly(&key, &run, &tmp.path, &["sibling", "trace.log"], &full_key);
688	    // Neither the full key nor the 10-byte fragment that briefly sat on
689	    // disk may leak, as raw bytes or in hex.
690	    assert_key_material_not_leaked(&run, &full_key, "the rejected key");
691	    assert_key_material_not_leaked(&run, &partial_key, "the saved key fragment");
692	    let stderr = String::from_utf8_lossy(&run.err);
693	    assert!(
694	        stderr.contains("incomplete write"),
695	        "stderr should explain the key file was not fully written, got: {stderr}"
696	    );
697	
698	    sibling.assert_untouched();
699	    assert_eq!(
700	        mode_of(&tmp.path),
701	        parent_mode_before,
702	        "parent directory permissions must be untouched"
703	    );
704	
705	    // The 10-byte partial file was removed (not zero-padded to 32 bytes,
706	    // not left behind): a fault-free retry at the same path succeeds.
707	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
708	    let run2 = run_keygen(&key, 0o022, &so, &[], &trace2);
709	    assert_success(&key, &run2);
710	    sibling.assert_untouched();
711	}
