1	/*
2	 * permfail.c -- LD_PRELOAD shim for wrapfile keygen permission tests.
3	 *
4	 * Two jobs:
5	 *
6	 * 1. Tracing. For the file the guest creates with open(O_CREAT|...) it logs
7	 *    to WRAPFILE_TEST_TRACE_FILE (one line per event):
8	 *
9	 *      BORN        fd=N mode=0oNNNN   mode right after the creating open()
10	 *      FCHMOD      ret=0/-1 mode=0oNNNN
11	 *      FSTAT       ret=0/-1 mode=0oNNNN size=N   (mode reported to guest)
12	 *      FIRST_WRITE mode=0oNNNN size=N  immediately before the first write()
13	 *      WRITE       off=N req=N ret=N [hex=...]   each write() on the key fd;
14	 *                    ret=-1 errno=ENAME for injected faults
15	 *      FSYNC       ret=0/-1
16	 *
17	 *    FIRST_WRITE with mode=0o600 and size=0 proves the program had both set
18	 *    and *confirmed* 0600 before a single key byte was written. The WRITE
19	 *    stream (off ascending from 0 with no gaps or overlaps, ending at 32)
20	 *    proves partial writes were resumed without duplicating or dropping
21	 *    bytes, and FSYNC ret=0 after the last WRITE proves the key was synced
22	 *    to disk before the program reported success.
23	 *
24	 * 2. Fault injection (only for a descriptor the guest itself created):
25	 *      WRAPFILE_TEST_FAIL_FCHMOD=1      fchmod() fails with EPERM
26	 *      WRAPFILE_TEST_FAIL_FSTAT=1       fstat()/fstat64() fail (EBADF), so the
27	 *                                        resulting mode cannot be confirmed
28	 *      WRAPFILE_TEST_LIE_MODE=OCTAL     fstat reports these low 12 mode bits
29	 *                                        (e.g. 0000) while the real fchmod
30	 *                                        succeeded -- a filesystem that silently
31	 *                                        stores another mode
32	 *      WRAPFILE_TEST_PARTIAL_WRITE=N    write() accepts at most N bytes per
33	 *                                        call (a kernel that only takes part
34	 *                                        of the buffer)
35	 *      WRAPFILE_TEST_WRITE_EINTR=N      the first N write() calls fail with
36	 *                                        EINTR, then writes succeed normally
37	 *      WRAPFILE_TEST_FAIL_WRITE_AFTER=N after N bytes in total have landed,
38	 *                                        write() fails with EIO (the last
39	 *                                        partial write is clamped so exactly
40	 *                                        N bytes are on disk before the error)
41	 *      WRAPFILE_TEST_WRITE_ZERO_AFTER=N once N bytes in total have landed,
42	 *                                        write() returns 0 without setting
43	 *                                        errno: no progress, yet no error
44	 *                                        either (the last real write is
45	 *                                        clamped so exactly N bytes are on
46	 *                                        disk first). Distinct from
47	 *                                        PARTIAL_WRITE (some progress every
48	 *                                        call) and from EINTR/EIO (an error
49	 *                                        is reported).
50	 *      WRAPFILE_TEST_FAIL_FSYNC=1       fsync() fails with EIO
51	 *      WRAPFILE_TEST_TRACE_BYTES=1      append hex=... of the bytes each
52	 *                                        write() actually landed, so tests can
53	 *                                        reconstruct the byte stream and check
54	 *                                        nothing secret leaks to stdout/stderr
55	 *
56	 * The shim only activates inside an executable whose basename starts with
57	 * "wrapfile" (checked via /proc/self/exe), so a wrapper shell used to set
58	 * the umask is never affected. After execve() the guest starts with a fresh
59	 * table, so only the guest's own O_CREAT descriptor (the key file) is
60	 * tracked; stdout/stderr and unrelated fds pass through untouched.
61	 */
62	
63	#define _GNU_SOURCE
64	#include <dlfcn.h>
65	#include <errno.h>
66	#include <fcntl.h>
67	#include <stdarg.h>
68	#include <stdio.h>
69	#include <stdlib.h>
70	#include <string.h>
71	#include <sys/stat.h>
72	#include <sys/syscall.h>
73	#include <unistd.h>
74	
75	#ifndef O_CLOEXEC
76	#define O_CLOEXEC 0
77	#endif
78	
79	typedef int (*open_fn)(const char *, int, ...);
80	typedef int (*open64_fn)(const char *, int, ...);
81	typedef int (*fchmod_fn)(int, mode_t);
82	typedef int (*fstat_fn)(int, struct stat *);
83	typedef int (*fstat64_fn)(int, struct stat64 *);
84	typedef ssize_t (*write_fn)(int, const void *, size_t);
85	typedef int (*fsync_fn)(int);
86	
87	static open_fn    real_open;
88	static open64_fn  real_open64;
89	static fchmod_fn  real_fchmod;
90	static fstat_fn   real_fstat;
91	static fstat64_fn real_fstat64;
92	static write_fn   real_write;
93	static fsync_fn   real_fsync;
94	
95	static int cfg_fail_fchmod = 0;
96	static int cfg_fail_fstat  = 0;
97	static int cfg_lie_mode    = -1; /* -1 = disabled */
98	static long cfg_partial_write = 0;      /* 0 = disabled */
99	static int  cfg_write_eintr = 0;        /* first N write() calls fail EINTR */
100	static long cfg_fail_write_after = -1;  /* -1 = disabled */
101	static long cfg_write_zero_after = -1;  /* -1 = disabled */
102	static int  cfg_fail_fsync = 0;
103	static int  cfg_trace_bytes = 0;
104	
105	/* Descriptor table: fds the guest created with O_CREAT. */
106	#define FD_MAX 1024
107	static unsigned char tracked[FD_MAX];
108	static unsigned char written[FD_MAX];
109	static unsigned char eintr_left[FD_MAX];
110	static unsigned long long written_total[FD_MAX];
111	
112	/* ----- activation: only inside the wrapfile executable ----- */
113	
114	static int process_active(void)
115	{
116	    static int cached = -1;
117	    if (cached != -1)
118	        return cached;
119	
120	    char buf[512];
121	    ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf) - 1);
122	    if (n <= 0) {
123	        cached = 0;
124	        return 0;
125	    }
126	    buf[n] = '\0';
127	    const char *base = strrchr(buf, '/');
128	    base = base ? base + 1 : buf;
129	    cached = (strncmp(base, "wrapfile", 8) == 0) ? 1 : 0;
130	    return cached;
131	}
132	
133	static void load_config(void)
134	{
135	    static int loaded = 0;
136	    if (loaded)
137	        return;
138	    loaded = 1;
139	
140	    const char *v;
141	    if ((v = getenv("WRAPFILE_TEST_FAIL_FCHMOD")) && v[0] == '1')
142	        cfg_fail_fchmod = 1;
143	    if ((v = getenv("WRAPFILE_TEST_FAIL_FSTAT")) && v[0] == '1')
144	        cfg_fail_fstat = 1;
145	    if ((v = getenv("WRAPFILE_TEST_TRACE_FILE")))
146	        (void)v; /* opened lazily on first trace() */
147	    if ((v = getenv("WRAPFILE_TEST_LIE_MODE")) && v[0] != '\0')
148	        cfg_lie_mode = (int)strtol(v, NULL, 8);
149	    if ((v = getenv("WRAPFILE_TEST_PARTIAL_WRITE")) && v[0] != '\0')
150	        cfg_partial_write = strtol(v, NULL, 10);
151	    if ((v = getenv("WRAPFILE_TEST_WRITE_EINTR")) && v[0] != '\0')
152	        cfg_write_eintr = atoi(v);
153	    if ((v = getenv("WRAPFILE_TEST_FAIL_WRITE_AFTER")) && v[0] != '\0')
154	        cfg_fail_write_after = strtol(v, NULL, 10);
155	    if ((v = getenv("WRAPFILE_TEST_WRITE_ZERO_AFTER")) && v[0] != '\0')
156	        cfg_write_zero_after = strtol(v, NULL, 10);
157	    if ((v = getenv("WRAPFILE_TEST_FAIL_FSYNC")) && v[0] == '1')
158	        cfg_fail_fsync = 1;
159	    if ((v = getenv("WRAPFILE_TEST_TRACE_BYTES")) && v[0] == '1')
160	        cfg_trace_bytes = 1;
161	}
162	
163	static int trace_fd(void)
164	{
165	    static int fd = -2; /* -2 = not initialised */
166	    if (fd != -2)
167	        return fd;
168	
169	    const char *path = getenv("WRAPFILE_TEST_TRACE_FILE");
170	    if (!path || !path[0]) {
171	        fd = -1;
172	        return fd;
173	    }
174	    /*
175	     * Raw openat(AT_FDCWD, ...) syscall rather than open(): going through
176	     * our own open() wrapper inside the wrapfile process would mark the
177	     * trace file as a tracked, created descriptor and mis-attribute writes
178	     * to it. The syscall bypasses all libc interposition.
179	     */
180	    fd = (int)syscall(SYS_openat, AT_FDCWD, path,
181	                      O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
182	    return fd;
183	}
184	
185	static void trace(const char *fmt, ...)
186	{
187	    int fd = trace_fd();
188	    if (fd < 0)
189	        return;
190	    va_list ap;
191	    va_start(ap, fmt);
192	    vdprintf(fd, fmt, ap);
193	    va_end(ap);
194	}
195	
196	/* ----- per-descriptor helpers ----- */
197	
198	static fstat_fn get_real_fstat(void)
199	{
200	    if (!real_fstat)
201	        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
202	    return real_fstat;
203	}
204	
205	static int is_tracked(int fd)
206	{
207	    return fd >= 0 && fd < FD_MAX && tracked[fd];
208	}
209	
210	/* malloc'd lowercase hex of n bytes, or NULL. Caller frees. */
211	static char *hex_encode(const unsigned char *p, size_t n)
212	{
213	    static const char digits[] = "0123456789abcdef";
214	    char *hex = malloc(n * 2 + 1);
215	    if (!hex)
216	        return NULL;
217	    for (size_t i = 0; i < n; i++) {
218	        hex[i * 2] = digits[p[i] >> 4];
219	        hex[i * 2 + 1] = digits[p[i] & 0xf];
220	    }
221	    hex[n * 2] = '\0';
222	    return hex;
223	}
224	
225	static void note_created(int fd)
226	{
227	    if (fd < 0 || fd >= FD_MAX)
228	        return;
229	    tracked[fd] = 1;
230	    written[fd] = 0;
231	    eintr_left[fd] = (cfg_write_eintr > 0 && cfg_write_eintr < 256)
232	                         ? (unsigned char)cfg_write_eintr
233	                         : 0;
234	    written_total[fd] = 0;
235	
236	    struct stat st;
237	    fstat_fn fn = get_real_fstat();
238	    if (fn && fn(fd, &st) == 0) {
239	        trace("BORN fd=%d mode=0%04o\n", fd,
240	              (unsigned)(st.st_mode & 07777));
241	    }
242	}
243	
244	/*
245	 * Shared fstat handling for tracked fds: perform the real fstat (via the
246	 * passed function), apply fault/lie policy, log the result, and tell the
247	 * caller what to return.
248	 */
249	static int handle_fstat(int fd, void *st, int is64)
250	{
251	    int rc = is64 ? real_fstat64(fd, (struct stat64 *)st)
252	                  : real_fstat(fd, (struct stat *)st);
253	
254	    if (!is_tracked(fd))
255	        return rc;
256	
257	    if (rc != 0) {
258	        trace("FSTAT ret=-1 mode=00000 size=0\n");
259	        return rc;
260	    }
261	
262	    mode_t real_mode;
263	    off_t real_size;
264	    if (is64) {
265	        struct stat64 *s = (struct stat64 *)st;
266	        real_mode = s->st_mode;
267	        real_size = s->st_size;
268	    } else {
269	        struct stat *s = (struct stat *)st;
270	        real_mode = s->st_mode;
271	        real_size = s->st_size;
272	    }
273	
274	    if (cfg_fail_fstat) {
275	        trace("FSTAT ret=-1 mode=0%04o size=%lld\n",
276	              (unsigned)(real_mode & 07777), (long long)real_size);
277	        errno = EBADF;
278	        return -1;
279	    }
280	
281	    mode_t reported = real_mode;
282	    if (cfg_lie_mode >= 0) {
283	        reported = (real_mode & ~(mode_t)07777) | (mode_t)cfg_lie_mode;
284	        if (is64)
285	            ((struct stat64 *)st)->st_mode = reported;
286	        else
287	            ((struct stat *)st)->st_mode = reported;
288	    }
289	
290	    trace("FSTAT ret=0 mode=0%04o size=%lld\n",
291	          (unsigned)(reported & 07777), (long long)real_size);
292	    return 0;
293	}
294	
295	/* ----- intercepted libc functions ----- */
296	
297	int open(const char *path, int flags, ...)
298	{
299	    if (!real_open)
300	        real_open = (open_fn)dlsym(RTLD_NEXT, "open");
301	
302	    mode_t mode = 0;
303	    if (flags & O_CREAT) {
304	        va_list ap;
305	        va_start(ap, flags);
306	        mode = va_arg(ap, mode_t);
307	        va_end(ap);
308	    }
309	
310	    int fd = real_open(path, flags, mode);
311	
312	    if (process_active() && (flags & O_CREAT)) {
313	        load_config();
314	        if (fd >= 0)
315	            note_created(fd);
316	        trace("OPEN ret=%d flags=0%o mode=0%04o\n", fd, flags,
317	              (unsigned)(mode & 07777));
318	    }
319	    return fd;
320	}
321	
322	int open64(const char *path, int flags, ...)
323	{
324	    if (!real_open64)
325	        real_open64 = (open64_fn)dlsym(RTLD_NEXT, "open64");
326	
327	    mode_t mode = 0;
328	    if (flags & O_CREAT) {
329	        va_list ap;
330	        va_start(ap, flags);
331	        mode = va_arg(ap, mode_t);
332	        va_end(ap);
333	    }
334	
335	    int fd = real_open64(path, flags, mode);
336	
337	    if (process_active() && (flags & O_CREAT)) {
338	        load_config();
339	        if (fd >= 0)
340	            note_created(fd);
341	        trace("OPEN ret=%d flags=0%o mode=0%04o\n", fd, flags,
342	              (unsigned)(mode & 07777));
343	    }
344	    return fd;
345	}
346	
347	int fchmod(int fd, mode_t mode)
348	{
349	    if (!real_fchmod)
350	        real_fchmod = (fchmod_fn)dlsym(RTLD_NEXT, "fchmod");
351	
352	    if (!process_active())
353	        return real_fchmod(fd, mode);
354	    load_config();
355	
356	    if (is_tracked(fd) && cfg_fail_fchmod) {
357	        trace("FCHMOD ret=-1 mode=0%04o\n", (unsigned)(mode & 07777));
358	        errno = EPERM;
359	        return -1;
360	    }
361	
362	    int rc = real_fchmod(fd, mode);
363	    if (is_tracked(fd)) {
364	        trace("FCHMOD ret=%d mode=0%04o\n", rc,
365	              (unsigned)(mode & 07777));
366	    }
367	    return rc;
368	}
369	
370	int fstat(int fd, struct stat *st)
371	{
372	    if (!real_fstat)
373	        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
374	    if (!process_active())
375	        return real_fstat(fd, st);
376	    load_config();
377	    if (!is_tracked(fd))
378	        return real_fstat(fd, st);
379	    return handle_fstat(fd, st, 0);
380	}
381	
382	int fstat64(int fd, struct stat64 *st)
383	{
384	    if (!real_fstat64)
385	        real_fstat64 = (fstat64_fn)dlsym(RTLD_NEXT, "fstat64");
386	    if (!process_active())
387	        return real_fstat64(fd, st);
388	    load_config();
389	    if (!is_tracked(fd))
390	        return real_fstat64(fd, st);
391	    return handle_fstat(fd, st, 1);
392	}
393	
394	ssize_t write(int fd, const void *buf, size_t count)
395	{
396	    if (!real_write)
397	        real_write = (write_fn)dlsym(RTLD_NEXT, "write");
398	
399	    if (!process_active() || !is_tracked(fd))
400	        return real_write(fd, buf, count);
401	    load_config();
402	
403	    if (!written[fd]) {
404	        written[fd] = 1;
405	        struct stat st;
406	        fstat_fn fn = get_real_fstat();
407	        if (fn && fn(fd, &st) == 0) {
408	            trace("FIRST_WRITE mode=0%04o size=%lld\n",
409	                  (unsigned)(st.st_mode & 07777),
410	                  (long long)st.st_size);
411	        } else {
412	            trace("FIRST_WRITE mode=unknown size=unknown\n");
413	        }
414	    }
415	
416	    /* A recoverable interruption: the call fails before any byte is
417	     * consumed, and the next call succeeds. */
418	    if (eintr_left[fd] > 0) {
419	        eintr_left[fd]--;
420	        trace("WRITE ret=-1 errno=EINTR\n");
421	        errno = EINTR;
422	        return -1;
423	    }
424	
425	    /* A kernel that only accepts part of the buffer per call. */
426	    size_t allowed = count;
427	    if (cfg_partial_write > 0 && allowed > (size_t)cfg_partial_write)
428	        allowed = (size_t)cfg_partial_write;
429	
430	    /* An unrecoverable error once N bytes have landed. */
431	    if (cfg_fail_write_after >= 0) {
432	        long long remaining =
433	            (long long)cfg_fail_write_after - (long long)written_total[fd];
434	        if (remaining <= 0) {
435	            trace("WRITE ret=-1 errno=EIO off=%llu\n", written_total[fd]);
436	            errno = EIO;
437	            return -1;
438	        }
439	        if (allowed > (size_t)remaining)
440	            allowed = (size_t)remaining;
441	    }
442	
443	    /* No progress and no error: once N bytes have landed, write() accepts
444	     * 0 bytes and reports success-with-zero -- neither a partial write
445	     * (which still advances) nor a recoverable interruption (which reports
446	     * EINTR). The offered bytes are traced (when TRACE_BYTES is on) so the
447	     * test can verify the rejected key material never leaks. */
448	    if (cfg_write_zero_after >= 0) {
449	        long long remaining =
450	            (long long)cfg_write_zero_after - (long long)written_total[fd];
451	        if (remaining <= 0) {
452	            if (cfg_trace_bytes) {
453	                char *hex = hex_encode(buf, allowed);
454	                if (hex) {
455	                    trace("WRITE off=%llu req=%zu ret=0 hex=%s\n",
456	                          written_total[fd], allowed, hex);
457	                    free(hex);
458	                } else {
459	                    trace("WRITE off=%llu req=%zu ret=0\n",
460	                          written_total[fd], allowed);
461	                }
462	            } else {
463	                trace("WRITE off=%llu req=%zu ret=0\n",
464	                      written_total[fd], allowed);
465	            }
466	            return 0;
467	        }
468	        if (allowed > (size_t)remaining)
469	            allowed = (size_t)remaining;
470	    }
471	
472	    ssize_t r = real_write(fd, buf, allowed);
473	    if (r > 0) {
474	        unsigned long long off = written_total[fd];
475	        written_total[fd] += (unsigned long long)r;
476	        if (cfg_trace_bytes) {
477	            char *hex = hex_encode(buf, (size_t)r);
478	            if (hex) {
479	                trace("WRITE off=%llu req=%zu ret=%zd hex=%s\n",
480	                      off, allowed, r, hex);
481	                free(hex);
482	            } else {
483	                trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
484	            }
485	        } else {
486	            trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
487	        }
488	    } else {
489	        trace("WRITE off=%llu req=%zu ret=%zd\n",
490	              written_total[fd], allowed, r);
491	    }
492	    return r;
493	}
494	
495	int fsync(int fd)
496	{
497	    if (!real_fsync)
498	        real_fsync = (fsync_fn)dlsym(RTLD_NEXT, "fsync");
499	
500	    if (!process_active())
501	        return real_fsync(fd);
502	    load_config();
503	
504	    if (is_tracked(fd) && cfg_fail_fsync) {
505	        trace("FSYNC ret=-1\n");
506	        errno = EIO;
507	        return -1;
508	    }
509	
510	    int rc = real_fsync(fd);
511	    if (is_tracked(fd))
512	        trace("FSYNC ret=%d\n", rc);
513	    return rc;
514	}
515

