1	//! Regression coverage for the keygen file-permission contract on Unix.
2	//!
3	//! What is protected here (see README "文件权限"):
4	//!
5	//! * Under umask 0022 / 0000 / 0777 a key is generated successfully only as
6	//!   exactly 32 raw bytes with final mode exactly 0600 -- owner read+write,
7	//!   no group/other bits, no extra bits; 0400/0200/0000 are not success.
8	//! * The file is never group/other-accessible, not even for an instant: the
9	//!   mode observed right after creation already carries no group/other bits.
10	//! * Permissions are both set to and *confirmed* as exactly 0600 before any
11	//!   key byte is written. This cannot be observed from the final file, so a
12	//!   small LD_PRELOAD shim (tests/support/permfail) traces the program's
13	//!   open/fchmod/fstat/write calls from inside the process.
14	//! * If the filesystem rejects the required mode (fchmod fails) or the mode
15	//!   cannot be confirmed (fstat fails or reports something other than 0600),
16	//!   keygen exits 1, reports the permission problem on stderr, prints no
17	//!   success message, writes no key bytes, and removes the partial file --
18	//!   without touching pre-existing files, directories, symlinks, or the
19	//!   parent directory.
20	//! * Existing CLI behaviour (--version, usage/exit code 2) is unchanged.
21	#![cfg(unix)]
22	
23	use std::collections::HashMap;
24	use std::fs;
25	use std::os::unix::fs::{MetadataExt, PermissionsExt};
26	use std::path::{Path, PathBuf};
27	use std::process::Command;
28	use std::sync::atomic::{AtomicU64, Ordering};
29	
30	const KEY_LEN: usize = 32;
31	const MODE_0600: u32 = 0o600;
32	const UMASKS: [u32; 3] = [0o022, 0o000, 0o777];
33	
34	fn bin() -> PathBuf {
35	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
36	}
37	
38	fn permfail_so() -> Option<PathBuf> {
39	    option_env!("WRAPFILE_PERMFAIL_SO").map(PathBuf::from)
40	}
41	
42	// ---------------------------------------------------------------------------
43	// scratch directory
44	// ---------------------------------------------------------------------------
45	
46	struct Tmp {
47	    path: PathBuf,
48	}
49	
50	impl Tmp {
51	    fn new(label: &str) -> Tmp {
52	        static SEQ: AtomicU64 = AtomicU64::new(0);
53	        let path = std::env::temp_dir().join(format!(
54	            "wrapfile-keygen-tests-{}-{}-{}",
55	            std::process::id(),
56	            label,
57	            SEQ.fetch_add(1, Ordering::Relaxed)
58	        ));
59	        fs::create_dir_all(&path).unwrap();
60	        // Don't let the harness process's own (possibly strict) umask decide
61	        // the scratch dir's mode: keygen needs a writable parent, and every
62	        // test sets the umask it cares about inside the child shell.
63	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
64	        Tmp { path }
65	    }
66	
67	    fn child(&self, name: impl AsRef<Path>) -> PathBuf {
68	        self.path.join(name)
69	    }
70	}
71	
72	impl Drop for Tmp {
73	    fn drop(&mut self) {
74	        // A read-only-parent test may have stripped write permission;
75	        // restore it so teardown can remove the tree.
76	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
77	        let _ = fs::remove_dir_all(&self.path);
78	    }
79	}
80	
81	// ---------------------------------------------------------------------------
82	// running the binary
83	// ---------------------------------------------------------------------------
84	
85	struct Run {
86	    rc: i32,
87	    out: Vec<u8>,
88	    err: Vec<u8>,
89	}
90	
91	fn run_version() -> Run {
92	    let o = Command::new(bin()).arg("--version").output().unwrap();
93	    Run {
94	        rc: o.status.code().unwrap_or(-1),
95	        out: o.stdout,
96	        err: o.stderr,
97	    }
98	}
99	
100	fn run_args(args: &[&str]) -> Run {
101	    let o = Command::new(bin()).args(args).output().unwrap();
102	    Run {
103	        rc: o.status.code().unwrap_or(-1),
104	        out: o.stdout,
105	        err: o.stderr,
106	    }
107	}
108	
109	/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
110	/// wrapper (`umask MMMM; exec "$@"`), optionally with the permfail shim
111	/// preloaded and a trace file configured.
112	fn run_keygen(
113	    key: &Path,
114	    umask: u32,
115	    preload_so: Option<&Path>,
116	    extra_env: &[(&str, &str)],
117	    trace_file: Option<&Path>,
118	) -> Run {
119	    let mut cmd = Command::new("/bin/sh");
120	    cmd.arg("-c")
121	        .arg(format!("umask {umask:04o}; exec \"$@\""))
122	        .arg("sh")
123	        .arg(bin())
124	        .arg("keygen")
125	        .arg(key);
126	
127	    if let Some(so) = preload_so {
128	        cmd.env("LD_PRELOAD", so);
129	    }
130	    for (k, v) in extra_env {
131	        cmd.env(k, v);
132	    }
133	    if let Some(t) = trace_file {
134	        cmd.env("WRAPFILE_TEST_TRACE_FILE", t);
135	    }
136	
137	    let o = cmd.output().unwrap();
138	    Run {
139	        rc: o.status.code().unwrap_or(-1),
140	        out: o.stdout,
141	        err: o.stderr,
142	    }
143	}
144	
145	// ---------------------------------------------------------------------------
146	// shim trace log
147	// ---------------------------------------------------------------------------
148	
149	struct Event {
150	    kind: String,
151	    attrs: HashMap<String, String>,
152	    index: usize,
153	}
154	
155	impl Event {
156	    fn get(&self, key: &str) -> Option<&str> {
157	        self.attrs.get(key).map(String::as_str)
158	    }
159	
160	    fn mode(&self) -> Option<u32> {
161	        self.get("mode").and_then(|v| u32::from_str_radix(v, 8).ok())
162	    }
163	
164	    fn size(&self) -> Option<u64> {
165	        self.get("size").and_then(|v| v.parse().ok())
166	    }
167	
168	    fn ret(&self) -> Option<i32> {
169	        self.get("ret").and_then(|v| v.parse().ok())
170	    }
171	}
172	
173	fn parse_trace(path: &Path) -> Vec<Event> {
174	    let text = fs::read_to_string(path).unwrap();
175	    text.lines()
176	        .enumerate()
177	        .map(|(index, line)| {
178	            let mut it = line.split_whitespace();
179	            let kind = it.next().unwrap_or("").to_string();
180	            let attrs = it
181	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
182	                .collect();
183	            Event { kind, attrs, index }
184	        })
185	        .collect()
186	}
187	
188	fn first_index(events: &[Event], pred: impl Fn(&Event) -> bool) -> Option<usize> {
189	    events.iter().position(pred)
190	}
191	
192	/// Create the trace file up front (mode 0644) so that it stays readable even
193	/// when the child runs under umask 0777 -- the shim opens it O_APPEND.
194	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
195	    let p = dir.join(name);
196	    fs::File::create(&p).unwrap();
197	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
198	    p
199	}
200	
201	// ---------------------------------------------------------------------------
202	// filesystem assertions
203	// ---------------------------------------------------------------------------
204	
205	fn mode_of(path: &Path) -> u32 {
206	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
207	}
208	
209	fn assert_key_file_ok(path: &Path, run: &Run) -> Vec<u8> {
210	    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
211	    assert!(run.err.is_empty(), "unexpected stderr: {}", String::from_utf8_lossy(&run.err));
212	
213	    let meta = fs::metadata(path).expect("key file should exist on success");
214	    assert_eq!(meta.len() as usize, KEY_LEN, "key must be exactly 32 bytes");
215	
216	    let mode = meta.mode() & 0o7777;
217	    // One assertion that carries the whole contract: exactly 0600 -- owner
218	    // r+w both present, all group/other bits off, no setuid/setgid/sticky.
219	    assert_eq!(
220	        mode, MODE_0600,
221	        "key file mode must be exactly 0600 (owner rw only), got {mode:04o}"
222	    );
223	
224	    let expected_stdout =
225	        format!("Key saved to {}\n", path.display()).into_bytes();
226	    assert_eq!(run.out, expected_stdout, "stdout should only announce the save location");
227	
228	    let bytes = fs::read(path).unwrap();
229	    assert_eq!(bytes.len(), KEY_LEN);
230	    assert!(
231	        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
232	        "key bytes must never appear on stdout/stderr"
233	    );
234	    bytes
235	}
236	
237	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
238	    needle.is_empty()
239	        || haystack
240	            .windows(needle.len())
241	            .any(|w| w == needle)
242	}
243	
244	fn assert_permission_failure_cleaned(path: &Path, run: &Run, dir: &Path, allowed_entries: &[&str]) {
245	    assert_eq!(run.rc, 1, "permission problems must fail with exit code 1");
246	    assert!(run.out.is_empty(), "no success message on failure, got {}", String::from_utf8_lossy(&run.out));
247	    assert!(!run.err.is_empty(), "stderr must explain the failure");
248	    let stderr = String::from_utf8_lossy(&run.err);
249	    assert!(
250	        stderr.contains("0600") || stderr.to_lowercase().contains("permission"),
251	        "stderr must describe the permission problem, got: {stderr}"
252	    );
253	    assert!(!path.exists(), "the failed generation's target must be removed");
254	
255	    // Nothing else left behind in the parent directory.
256	    let mut leftovers: Vec<String> = fs::read_dir(dir)
257	        .unwrap()
258	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
259	        .filter(|n| !allowed_entries.contains(&n.as_str()))
260	        .collect();
261	    leftovers.sort();
262	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
263	}
264	
265	// A pre-existing object that must survive a failed keygen byte-for-byte.
266	struct Sentinel {
267	    path: PathBuf,
268	    bytes: Vec<u8>,
269	    mode: u32,
270	    inode: u64,
271	}
272	
273	impl Sentinel {
274	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
275	        let path = dir.join(name);
276	        fs::write(&path, bytes).unwrap();
277	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
278	        let meta = fs::metadata(&path).unwrap();
279	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
280	    }
281	
282	    fn assert_untouched(&self) {
283	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
284	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
285	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
286	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
287	    }
288	}
289	
290	// ---------------------------------------------------------------------------
291	// tests
292	// ---------------------------------------------------------------------------
293	
294	#[test]
295	fn succeeds_with_exactly_0600_under_all_umasks() {
296	    let so = permfail_so();
297	    let mut keys: Vec<Vec<u8>> = Vec::new();
298	
299	    for umask in UMASKS {
300	        let tmp = Tmp::new("success");
301	        let key = tmp.child(format!("key-{umask:04o}"));
302	        let trace = prepare_trace(&tmp.path, "trace.log");
303	
304	        let run = run_keygen(&key, umask, so.as_deref(), &[], Some(&trace));
305	        let bytes = assert_key_file_ok(&key, &run);
306	        keys.push(bytes);
307	
308	        if let Some(events) = so.as_ref().map(|_| parse_trace(&trace)) {
309	            // The descriptor the program created was never group/other
310	            // accessible, not even at birth. Under umask 0777 the owner
311	            // bits are also stripped at birth (0000) and repaired later.
312	            let born = events.iter().find(|e| e.kind == "BORN").expect("BORN event");
313	            assert_eq!(born.mode().unwrap() & 0o077, 0, "group/other bits must be off from creation");
314	            let expected_born = if umask == 0o777 { 0o000 } else { 0o600 };
315	            assert_eq!(born.mode().unwrap(), expected_born,
316	                "umask {umask:04o} should yield birth mode {expected_born:04o}");
317	        }
318	    }
319	
320	    // Distinct runs draw independent random keys; none is the zero key.
321	    for k in &keys {
322	        assert!(k.iter().any(|&b| b != 0), "key must not be all zeroes");
323	    }
324	    assert_ne!(keys[0], keys[1]);
325	    assert_ne!(keys[1], keys[2]);
326	    assert_ne!(keys[0], keys[2]);
327	}
328	
329	#[test]
330	fn permissions_set_and_confirmed_before_any_key_byte() {
331	    let Some(so) = permfail_so() else {
332	        eprintln!("skipping: permfail shim not available on this target");
333	        return;
334	    };
335	
336	    for umask in UMASKS {
337	        let tmp = Tmp::new("before-write");
338	        let key = tmp.child("key");
339	        let trace = prepare_trace(&tmp.path, "trace.log");
340	
341	        let run = run_keygen(&key, umask, Some(&so), &[], Some(&trace));
342	        assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
343	        let events = parse_trace(&trace);
344	
345	        let first_write = first_index(&events, |e| e.kind == "FIRST_WRITE")
346	            .expect("the key must eventually be written");
347	        let w = &events[first_write];
348	
349	        // Immediately before the first write call: mode is exactly 0600 and
350	        // size is still 0 -- no key byte preceded the confirmation.
351	        assert_eq!(w.mode().unwrap(), MODE_0600,
352	            "mode at first write must be exactly 0600 (umask {umask:04o})");
353	        assert_eq!(w.size().unwrap(), 0,
354	            "file must be empty when 0600 is confirmed (umask {umask:04o})");
355	
356	        // fchmod set 0600 and an fstat confirmed it, both before the write.
357	        let chmod = first_index(&events, |e| {
358	            e.kind == "FCHMOD" && e.ret() == Some(0) && e.mode() == Some(MODE_0600)
359	        }).expect("fchmod(fd, 0600) must succeed");
360	        let confirm = first_index(&events, |e| {
361	            e.kind == "FSTAT"
362	                && e.ret() == Some(0)
363	                && e.mode() == Some(MODE_0600)
364	                && e.size() == Some(0)
365	        }).expect("an fstat must confirm exactly 0600 on an empty file");
366	        assert!(chmod < first_write, "fchmod must precede the first write");
367	        assert!(confirm < first_write, "confirmation must precede the first write");
368	
369	        // Every mode observation before the first write (birth included)
370	        // carries no group or other bits: the secret is never exposed while
371	        // open, even for an instant.
372	        for e in events.iter().take(first_write) {
373	            if e.kind == "BORN" || e.kind == "FSTAT" {
374	                if let Some(m) = e.mode() {
375	                    assert_eq!(m & 0o077, 0,
376	                        "group/other bits observed before write in event {}: {:04o}", e.index, m);
377	                }
378	            }
379	        }
380	
381	        // Final on-disk state matches what the trace promised.
382	        assert_eq!(mode_of(&key), MODE_0600);
383	        assert_eq!(fs::metadata(&key).unwrap().len() as usize, KEY_LEN);
384	    }
385	}
386	
387	#[test]
388	fn fchmod_rejection_fails_explains_and_cleans_up() {
389	    let Some(so) = permfail_so() else {
390	        eprintln!("skipping: permfail shim not available on this target");
391	        return;
392	    };
393	
394	    for umask in UMASKS {
395	        let tmp = Tmp::new("fchmod-fail");
396	        let key = tmp.child("key");
397	        let sibling = Sentinel::file(&tmp.path, "sibling", b"do-not-touch", 0o644);
398	        let parent_mode_before = mode_of(&tmp.path);
399	        let trace = prepare_trace(&tmp.path, "trace.log");
400	
401	        let run = run_keygen(
402	            &key,
403	            umask,
404	            Some(&so),
405	            &[("WRAPFILE_TEST_FAIL_FCHMOD", "1")],
406	            Some(&trace),
407	        );
408	
409	        assert_permission_failure_cleaned(&key, &run, &tmp.path, &["sibling", "trace.log"]);
410	        assert!(
411	            String::from_utf8_lossy(&run.err).contains("0600"),
412	            "stderr must name the required mode"
413	        );
414	        sibling.assert_untouched();
415	        assert_eq!(mode_of(&tmp.path), parent_mode_before, "parent dir mode must not change");
416	
417	        // The secret never reached a file whose mode could not be made 0600.
418	        let events = parse_trace(&trace);
419	        assert!(events.iter().any(|e| e.kind == "FCHMOD" && e.ret() == Some(-1)));
420	        assert!(
421	            events.iter().all(|e| e.kind != "FIRST_WRITE"),
422	            "no key bytes may be written when fchmod is rejected"
423	        );
424	    }
425	}
426	
427	#[test]
428	fn unconfirmable_mode_fails_and_cleans_up() {
429	    let Some(so) = permfail_so() else {
430	        eprintln!("skipping: permfail shim not available on this target");
431	        return;
432	    };
433	
434	    // (extra env, label): fstat itself failing, or the filesystem reporting
435	    // a stored mode other than 0600 (owner bits missing, or group bits added).
436	    let cases: &[(&[(&str, &str)], &str)] = &[
437	        (&[("WRAPFILE_TEST_FAIL_FSTAT", "1")], "fstat-io-failure"),
438	        (&[("WRAPFILE_TEST_LIE_MODE", "0000")], "reports-0000"),
439	        (&[("WRAPFILE_TEST_LIE_MODE", "0644")], "reports-0644"),
440	    ];
441	
442	    for (env, label) in cases {
443	        let tmp = Tmp::new("unconfirmable");
444	        let key = tmp.child(label);
445	        let sibling = Sentinel::file(&tmp.path, "sibling", b"keep", 0o600);
446	        let trace = prepare_trace(&tmp.path, format!("{label}.log"));
447	
448	        let run = run_keygen(&key, 0o022, Some(&so), env, Some(&trace));
449	        assert_permission_failure_cleaned(
450	            &key,
451	            &run,
452	            &tmp.path,
453	            &["sibling", &format!("{label}.log")],
454	        );
455	        sibling.assert_untouched();
456	
457	        let events = parse_trace(&trace);
458	        assert!(
459	            events.iter().all(|e| e.kind != "FIRST_WRITE"),
460	            "no key bytes may be written before the mode is confirmed ({label})"
461	        );
462	    }
463	}
464	
465	#[test]
466	fn existing_objects_are_never_modified() {
467	    // No shim needed: the target already exists, so creation must fail.
468	    for umask in UMASKS {
469	        // --- pre-existing regular file with a non-0600 mode and contents ---
470	        let tmp = Tmp::new("existing-file");
471	        let secret = b"pre-existing-key-material";
472	        let existing = Sentinel::file(&tmp.path, "key", secret, 0o640);
473	        let run = run_keygen(&existing.path, umask, None, &[], None);
474	        assert_eq!(run.rc, 1);
475	        assert!(run.out.is_empty());
476	        existing.assert_untouched();
477	
478	        // --- pre-existing directory ---
479	        let tmp = Tmp::new("existing-dir");
480	        let dir = tmp.child("adir");
481	        fs::create_dir(&dir).unwrap();
482	        fs::set_permissions(&dir, fs::Permissions::from_mode(0o755)).unwrap();
483	        let run = run_keygen(&dir, umask, None, &[], None);
484	        assert_eq!(run.rc, 1);
485	        assert!(run.out.is_empty());
486	        assert!(dir.is_dir());
487	        assert_eq!(mode_of(&dir), 0o755, "existing directory mode must not change");
488	
489	        // --- dangling symlink: never followed, never replaced ---
490	        let tmp = Tmp::new("dangling-symlink");
491	        let target = tmp.child("does-not-exist");
492	        let link = tmp.child("link");
493	        std::os::unix::fs::symlink(&target, &link).unwrap();
494	        let run = run_keygen(&link, umask, None, &[], None);
495	        assert_eq!(run.rc, 1);
496	        assert!(run.out.is_empty());
497	        let md = fs::symlink_metadata(&link).expect("symlink itself must remain");
498	        assert!(md.file_type().is_symlink(), "dangling symlink must not be replaced");
499	        assert_eq!(fs::read_link(&link).unwrap(), target);
500	        assert!(!target.exists(), "must not create the symlink target through the link");
501	
502	        // --- missing parent directory: not auto-created ---
503	        let tmp = Tmp::new("missing-parent");
504	        let key = tmp.child("missing/sub/key");
505	        let run = run_keygen(&key, umask, None, &[], None);
506	        assert_eq!(run.rc, 1);
507	        assert!(run.out.is_empty());
508	        assert!(!tmp.child("missing").exists(), "parent directories must not be created");
509	    }
510	}
511	
512	#[test]
513	fn failure_leaves_parent_and_siblings_untouched() {
514	    let Some(so) = permfail_so() else {
515	        eprintln!("skipping: permfail shim not available on this target");
516	        return;
517	    };
518	
519	    let tmp = Tmp::new("siblings");
520	    let key = tmp.child("key");
521	    let sibling = Sentinel::file(&tmp.path, "sibling", b"sibling-bytes", 0o644);
522	    let parent_mode_before = mode_of(&tmp.path);
523	    let trace = prepare_trace(&tmp.path, "trace.log");
524	
525	    let run = run_keygen(
526	        &key,
527	        0o022,
528	        Some(&so),
529	        &[("WRAPFILE_TEST_FAIL_FCHMOD", "1")],
530	        Some(&trace),
531	    );
532	    assert_eq!(run.rc, 1);
533	    assert!(!key.exists());
534	    sibling.assert_untouched();
535	    assert_eq!(mode_of(&tmp.path), parent_mode_before, "parent directory must be untouched");
536	
537	    // A retry *without* the fault succeeds normally and produces only the key.
538	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
539	    let run2 = run_keygen(&key, 0o022, Some(&so), &[], Some(&trace2));
540	    assert_key_file_ok(&key, &run2);
541	    sibling.assert_untouched();
542	}
