544	#[test]
545	fn version_and_argument_handling_unchanged() {
546	    // --version
547	    let v = run_version();
548	    assert_eq!(v.rc, 0);
549	    assert_eq!(String::from_utf8_lossy(&v.out), "wrapfile 0.1.0\n");
550	    assert!(v.err.is_empty());
551	
552	    let tmp = Tmp::new("cli");
553	
554	    // missing path / extra args / unknown option all exit 2 and create files.
555	    let cases: &[&[&str]] = &[
556	        &["keygen"],
557	        &["keygen", "a", "b"],
558	        &["keygen", "--bogus"],
559	    ];
560	    for args in cases {
561	        let before: Vec<String> = fs::read_dir(&tmp.path)
562	            .unwrap()
563	            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
564	            .collect();
565	        let run = run_args(args);
566	        assert_eq!(run.rc, 2, "args {args:?} should exit 2");
567	        assert!(
568	            String::from_utf8_lossy(&run.err).contains("Usage"),
569	            "usage must be printed on stderr for {args:?}"
570	        );
571	        let after: Vec<String> = fs::read_dir(&tmp.path)
572	            .unwrap()
573	            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
574	            .collect();
575	        assert_eq!(before, after, "argument errors must not create files ({args:?})");
576	    }
577	
578	    // Totally unknown invocation -> 2 as well.
579	    let run = run_args(&["frobnicate"]);
580	    assert_eq!(run.rc, 2);
581	}
