    let key = tmp.child("key");
    let trace = prepare_trace(&tmp.path, "trace.log");

    // close() releases the descriptor but reports EINTR: an interruption,
    // not an unrecoverable failure. The save is complete and must be
    // reported as usual.
    let run = run_keygen(
